"""LLM provider abstraction.

The provider key lives only on the backend (never exposed to the frontend).
When no API key is configured the StubProvider returns a deterministic answer
so the whole stack runs in development and CI without external calls or cost.
"""

import logging
import re
import time
from dataclasses import dataclass

from django.conf import settings

logger = logging.getLogger(__name__)

def _strip_think_blocks(text):
    """Remove <think>...</think> blocks generated by reasoning models."""
    if not text:
        return text
    # re.DOTALL ensures . matches newlines
    return re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL).strip()

@dataclass
class ChatResult:
    content: str
    input_tokens: int
    output_tokens: int
    model: str
    latency_ms: int


class StubProvider:
    """Offline fallback used when AI_STUB_MODE is on.

    Yangi arxitektura uchun: prompt turiga qarab mos stub javob qaytaradi.
    - Intent detection prompt → intent nomi (product_search, greeting, etc.)
    - Filter extraction prompt → JSON filtrlar
    - Response generation prompt → tabiiy tildagi javob
    """

    model = "stub"

    def chat(self, system, messages, max_tokens):
        import json as _json

        start = time.monotonic()
        last_user = next(
            (m["content"] for m in reversed(messages) if m["role"] == "user"), ""
        )
        lowered = last_user.lower()

        # Prompt turini aniqlash
        system_lower = system.lower()

        if "klassifikator" in system_lower or "intent" in system_lower:
            # ── Intent Detection ──
            content = self._detect_intent_stub(lowered, system)

        elif "filtrlarini ajratasan" in system_lower or '"filters"' in system_lower:
            # ── Filter Extraction ──
            content = self._extract_filters_stub(lowered, system)

        else:
            # ── Response Generation ──
            content = self._generate_response_stub(lowered)

        latency = int((time.monotonic() - start) * 1000)
        approx_in = sum(len(m["content"]) for m in messages) // 4
        return ChatResult(
            content=content,
            input_tokens=approx_in,
            output_tokens=len(content) // 4,
            model=self.model,
            latency_ms=latency,
        )

    @staticmethod
    def _detect_intent_stub(lowered, system):
        """Intent aniqlash uchun stub."""
        greetings = ("salom", "assalom", "привет", "здравствуй", "hi", "hello")
        if any(g in lowered for g in greetings):
            return "greeting"

        product_keywords = (
            "kerak", "bor mi", "ko'rsat", "top", "qidir",
            "sotib", "olmoqchi", "buyurtma", "нужн", "покаж",
            "хочу", "купить",
        )
        if any(k in lowered for k in product_keywords):
            return "product_search"

        curtain_keywords = (
            "parda", "mato", "material", "yuv", "rang",
            "штор", "ткан", "матери", "стир",
        )
        if any(k in lowered for k in curtain_keywords):
            # Agar parda bilan bog'liq, lekin material/rang aytilsa → product_search
            # Aks holda → information_question
            material_keywords = ("blackout", "baxmal", "atlas", "organza", "tyul")
            if any(m in lowered for m in material_keywords):
                return "product_search"
            return "information_question"

        return "information_question"

    @staticmethod
    def _extract_filters_stub(lowered, system):
        """Filter ajratish uchun stub."""
        import json as _json

        # System promptdan mavjud materiallarni ajratish
        found_materials = []
        for line in system.splitlines():
            line_stripped = line.strip()
            # "Materiallar: Blackout, Baxmal, ..." formatidan ajratish
            if line_stripped.startswith("Materiallar:"):
                mats = line_stripped[len("Materiallar:"):].strip()
                for m in mats.split(","):
                    m = m.strip()
                    if m and m.lower() in lowered:
                        found_materials.append(m)

        filters = {
            "intent": "product_search",
            "filters": {
                "materials": found_materials,
                "colors": [],
                "room": None,
                "style": None,
                "pattern": None,
                "category": None,
                "width": None,
                "height": None,
            },
            "missing": [],
        }
        return _json.dumps(filters, ensure_ascii=False)

    @staticmethod
    def _generate_response_stub(lowered):
        """Javob yaratish uchun stub."""
        greetings = ("salom", "assalom", "привет", "здравствуй")
        if any(g in lowered for g in greetings):
            return (
                "Assalomu alaykum! Men ZigZag AI maslahatchisiman. "
                "Sizga premium pardalar tanlashda qanday yordam bera olaman?"
            )
        return "Sizga mos pardalarni topib beraman!"


class AnthropicProvider:
    def __init__(self, model):
        import anthropic

        self.model = model
        self.client = anthropic.Anthropic(api_key=settings.ANTHROPIC_API_KEY)

    def chat(self, system, messages, max_tokens):
        if getattr(settings, "AI_DEBUG_TOKENS", False):
            logger.info("\n" + "="*50 + " AI FULL PROMPT (Anthropic) " + "="*50)
            logger.info("SYSTEM:\n%s\n", system)
            logger.info("MESSAGES:\n%s", messages)

        start = time.monotonic()
        response = self.client.messages.create(
            model=self.model,
            system=system,
            messages=messages,
            max_tokens=max_tokens,
        )
        latency = int((time.monotonic() - start) * 1000)
        content = "".join(block.text for block in response.content if block.type == "text")
        content = _strip_think_blocks(content)
        
        if getattr(settings, "AI_DEBUG_TOKENS", False):
            logger.info("\n" + "="*50 + " AI RESPONSE (Anthropic) " + "="*50)
            logger.info(content)
            logger.info("="*125 + "\n")

        return ChatResult(
            content=content,
            input_tokens=response.usage.input_tokens,
            output_tokens=response.usage.output_tokens,
            model=self.model,
            latency_ms=latency,
        )

class OpenAIProvider:
    def __init__(self, model):
        import openai

        self.model = model
        # VAQTINCHALIK: OpenRouter uchun base_url (testdan so'ng olib tashlashingiz mumkin)
        self.client = openai.OpenAI(
            api_key=settings.OPENAI_API_KEY,
            base_url="https://openrouter.ai/api/v1"
        )

    def chat(self, system, messages, max_tokens):
        if getattr(settings, "AI_DEBUG_TOKENS", False):
            logger.info("\n" + "="*50 + " AI FULL PROMPT (OpenAI) " + "="*50)
            logger.info("SYSTEM:\n%s\n", system)
            logger.info("MESSAGES:\n%s", messages)

        start = time.monotonic()
        api_messages = [{"role": "system", "content": system}] + messages
        response = self.client.chat.completions.create(
            model=self.model,
            messages=api_messages,
            max_tokens=max_tokens,
        )
        latency = int((time.monotonic() - start) * 1000)
        
        message_obj = response.choices[0].message
        content = getattr(message_obj, "content", None) or ""
        
        # OpenRouter reasoning fallback
        if not content and hasattr(message_obj, "reasoning") and message_obj.reasoning:
            # We skip reasoning block since the user doesn't want to see it
            pass

        content = _strip_think_blocks(content)
            
        if getattr(settings, "AI_DEBUG_TOKENS", False):
            logger.info("\n" + "="*50 + " AI RESPONSE (OpenAI) " + "="*50)
            logger.info(content)
            logger.info("="*122 + "\n")

        input_tokens = response.usage.prompt_tokens if response.usage else 0
        output_tokens = response.usage.completion_tokens if response.usage else 0
        return ChatResult(
            content=content,
            input_tokens=input_tokens,
            output_tokens=output_tokens,
            model=self.model,
            latency_ms=latency,
        )


def get_chat_provider(strong=False):
    if settings.AI_STUB_MODE:
        return StubProvider()
    
    provider_type = getattr(settings, "AI_PROVIDER", "anthropic").lower()
    model = settings.AI_CHAT_MODEL_STRONG if strong else settings.AI_CHAT_MODEL
    
    if provider_type == "openai":
        if not settings.OPENAI_API_KEY:
            return StubProvider()
        return OpenAIProvider(model)
        
    if not settings.ANTHROPIC_API_KEY:
        return StubProvider()
    return AnthropicProvider(model)
